// ─── グレード計算 ─────────────────────────────────────────────────
function gradeFromScore(s: number): string {
  if (s >= 85) return "◎"; if (s >= 70) return "○"; if (s >= 55) return "△"; return "▽";
}
function gradeLabelFromScore(s: number): string {
  if (s >= 85) return "最高の相性"; if (s >= 70) return "良い相性"; if (s >= 55) return "普通の相性"; return "要注意の相性";
}

// ─── コンテキストスコア ───────────────────────────────────────────
function contextScore(base: number, a: number, b: number, ctx: string): number {
  const leaderNums = new Set([1,8,22]);
  const supportNums = new Set([2,6,9]);
  const analyticalNums = new Set([4,7]);
  const creativeNums = new Set([3,5,11]);
  let adj = 0;
  if (ctx === "asBoss") {
    if (leaderNums.has(a)) adj += 8; if (supportNums.has(b)) adj += 5;
    if (supportNums.has(a)) adj -= 3; if (leaderNums.has(b)) adj -= 5;
  } else if (ctx === "asSubordinate") {
    if (supportNums.has(a) || analyticalNums.has(a)) adj += 5;
    if (leaderNums.has(b)) adj += 5;
    if (leaderNums.has(a) && leaderNums.has(b)) adj -= 8;
  } else if (ctx === "business") {
    if (leaderNums.has(a) || leaderNums.has(b)) adj += 5;
    if (analyticalNums.has(a) || analyticalNums.has(b)) adj += 3;
  } else if (ctx === "customer" || ctx === "seitai") {
    if (supportNums.has(a) || creativeNums.has(a)) adj += 8;
    if (a === 2 || a === 6) adj += 5;
  } else if (ctx === "friendship") {
    if (creativeNums.has(a) || creativeNums.has(b)) adj += 5;
    if (supportNums.has(a) || supportNums.has(b)) adj += 3;
  } else if (ctx === "instructor") {
    if (supportNums.has(a) || analyticalNums.has(a)) adj += 5;
    if (a === 6 || a === 9) adj += 5;
  }
  return Math.min(98, Math.max(20, base + adj));
}

// ─── エクスポート型 ───────────────────────────────────────────────
export interface CompatibilityContext {
  score: number; grade: string; title: string;
  dynamic: string; tipsForA: string[]; tipsForB: string[];
}

export interface CompatibilityResult {
  score: number; grade: string; gradeLabel: string;
  summary: string; strengths: string[]; challenges: string[]; deepNote: string;
  communicationKey: string; communicationDeep: string;
  lifePathScore: number; destinyScore: number; soulScore: number; personalityScore: number;
  contexts: {
    overall: CompatibilityContext; friendship: CompatibilityContext; business: CompatibilityContext;
    asBoss: CompatibilityContext; asSubordinate: CompatibilityContext; customer: CompatibilityContext;
    seitai: CompatibilityContext; instructor: CompatibilityContext;
  };
}

