// ─── メイン計算 ───────────────────────────────────────────────────
export function calcCompatibility(a: NumerologyResult, b: NumerologyResult): CompatibilityResult {
  const lpScore   = baseScore(a.lifePath,    b.lifePath);
  const destScore = baseScore(a.destiny,     b.destiny);
  const soulScore = baseScore(a.soul,        b.soul);
  const persScore = baseScore(a.personality, b.personality);
  const overall   = Math.round(lpScore * 0.4 + destScore * 0.25 + soulScore * 0.2 + persScore * 0.15);

  const key = pairKey(a.lifePath, b.lifePath);
  const entry = PAIR_DATA[key] ?? defaultEntry(a.lifePath, b.lifePath);

  const TITLES: Record<string, string> = {
    overall: "総合相性", friendship: "友人・プライベート", business: "ビジネスパートナー",
    asBoss: "AがBの上司の場合", asSubordinate: "AがBの部下の場合",
    customer: "A→B（お客様対応）", seitai: "整体師A→お客様B", instructor: "講師A→受講生B",
  };

  function buildCtx(ctxKey: keyof typeof entry.contexts): CompatibilityContext {
    const s = contextScore(overall, a.lifePath, b.lifePath, ctxKey);
    const ctx = entry.contexts[ctxKey];
    return { score: s, grade: gradeFromScore(s), title: TITLES[ctxKey], dynamic: ctx.dynamic, tipsForA: ctx.tipsForA, tipsForB: ctx.tipsForB };
  }

  return {
    score: overall, grade: gradeFromScore(overall), gradeLabel: gradeLabelFromScore(overall),
    summary: entry.summary, strengths: entry.strengths, challenges: entry.challenges, deepNote: entry.deepNote,
    communicationKey: entry.communicationKey, communicationDeep: entry.communicationDeep,
    lifePathScore: lpScore, destinyScore: destScore, soulScore: soulScore, personalityScore: persScore,
    contexts: {
      overall:       buildCtx("overall"),
      friendship:    buildCtx("friendship"),
      business:      buildCtx("business"),
      asBoss:        buildCtx("asBoss"),
      asSubordinate: buildCtx("asSubordinate"),
      customer:      buildCtx("customer"),
      seitai:        buildCtx("seitai"),
      instructor:    buildCtx("instructor"),
    },
  };
}
